import { listTools, callTool } from "./server.mjs";

const ok = [];
const fail = [];
function check(label, cond) {
  (cond ? ok : fail).push(label);
}

// listTools
const tools = await listTools();
check("listTools has catalog_search", tools.length === 1 && tools[0].name === "catalog_search");
check("query is required", tools[0].inputSchema.required.includes("query"));
check("additionalProperties false", tools[0].inputSchema.additionalProperties === false);
check("limit min 1 max 5", tools[0].inputSchema.properties.limit.minimum === 1 && tools[0].inputSchema.properties.limit.maximum === 5);

async function t(name, args) {
  try { return await callTool(name, args); }
  catch (e) { return { error: e.message }; }
}

// case-insensitive search
let r = await t("catalog_search", { query: "WIDGET", limit: 2 });
let body = JSON.parse(r.content[0].text);
check("case-insensitive i1,i2", body.items.map(i=>i.id).join(",") === "i1,i2");
check("next_offset present", body.next_offset === 2);

// page 2
r = await t("catalog_search", { query: "widget", offset: 2, limit: 2 });
body = JSON.parse(r.content[0].text);
check("page2 i3 only", body.items.map(i=>i.id).join(",") === "i3");
check("no next_offset on last", body.next_offset === undefined);

// defaults: offset 0, limit 2
r = await t("catalog_search", { query: "widget" });
body = JSON.parse(r.content[0].text);
check("defaults limit 2", body.items.length === 2);

// limit range 1-5
r = await t("catalog_search", { query: "widget", limit: 0 });
check("reject limit 0", r.error !== undefined);
r = await t("catalog_search", { query: "widget", limit: 6 });
check("reject limit 6", r.error !== undefined);

// offset non-negative integer
r = await t("catalog_search", { query: "widget", offset: -1 });
check("reject offset -1", r.error !== undefined);

// query required
r = await t("catalog_search", {});
check("query required", r.error !== undefined);

// unknown tool
r = await t("nope", { query: "x" });
check("unknown tool rejected", r.error !== undefined);

// extra argument
r = await t("catalog_search", { query: "widget", foo: "bar" });
check("extra arg rejected", r.error !== undefined);

// non-string query
r = await t("catalog_search", { query: 123 });
check("non-string query rejected", r.error !== undefined);

// limit 5 returns all 3 widgets
r = await t("catalog_search", { query: "widget", limit: 5 });
body = JSON.parse(r.content[0].text);
check("limit 5 all widgets", body.items.length === 3 && body.next_offset === undefined);

console.log("PASS:", ok.join("; "));
if (fail.length) { console.log("FAIL:", fail.join("; ")); process.exit(1); }
' 2>&1"}

